package org.apache.commons.math.complex;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.apache.commons.math.FieldElement;
import org.apache.commons.math.exception.NotPositiveException;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.apache.commons.math3.exception.NullArgumentException;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class Complex_tanh_TriageGen0Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testTanhNaN() {
        Complex c = Complex.NaN;
        Complex result = c.tanh();
        Assert.assertTrue("Result should be NaN", result.isNaN());
    }

    @Test
    public void testTanhZero() {
        Complex c = new Complex(0.0, 0.0);
        Complex result = c.tanh();
        Assert.assertEquals(0.0, result.getReal(), EPSILON);
        Assert.assertEquals(0.0, result.getImaginary(), EPSILON);
    }

    @Test
    public void testTanhRealOnly() {
        // tanh(x) for real x
        double x = 1.0;
        Complex c = new Complex(x, 0.0);
        Complex result = c.tanh();

        double expectedReal = Math.tanh(x);
        // For real x, imaginary part of tanh(x + 0i) is 0
        Assert.assertEquals(expectedReal, result.getReal(), EPSILON);
        Assert.assertEquals(0.0, result.getImaginary(), EPSILON);
    }

    @Test
    public void testTanhImaginaryOnly() {
        // tanh(iy) = i * tan(y)
        double y = 0.5;
        Complex c = new Complex(0.0, y);
        Complex result = c.tanh();

        // real part should be 0
        Assert.assertEquals(0.0, result.getReal(), EPSILON);
        // imaginary part should be tan(y)
        Assert.assertEquals(Math.tan(y), result.getImaginary(), EPSILON);
    }

    @Test
    public void testTanhComplex() {
        // Test with a specific complex number: 0.5 + 0.5i
        double re = 0.5;
        double im = 0.5;
        Complex c = new Complex(re, im);
        Complex result = c.tanh();

        // Manual calculation using the formula in the method:
        // real2 = 1.0, imag2 = 1.0
        // d = cosh(1.0) + cos(1.0)
        // real_part = sinh(1.0) / d
        // imag_part = sin(1.0) / d
        double real2 = 2.0 * re;
        double imag2 = 2.0 * im;
        double d = Math.cosh(real2) + Math.cos(imag2);
        double expectedReal = Math.sinh(real2) / d;
        double expectedImag = Math.sin(imag2) / d;

        Assert.assertEquals(expectedReal, result.getReal(), EPSILON);
        Assert.assertEquals(expectedImag, result.getImaginary(), EPSILON);
    }

    @Test
    public void testTanhLargeValues() {
        // Testing behavior with large real part (tanh(x) -> 1 as x -> inf)
        Complex c = new Complex(100.0, 0.0);
        Complex result = c.tanh();
        Assert.assertEquals(1.0, result.getReal(), EPSILON);
        Assert.assertEquals(0.0, result.getImaginary(), EPSILON);
    }

    @Test
    public void testTanhNegativeValues() {
        Complex c = new Complex(-1.0, -1.0);
        Complex result = c.tanh();

        double re = -1.0;
        double im = -1.0;
        double real2 = 2.0 * re;
        double imag2 = 2.0 * im;
        double d = Math.cosh(real2) + Math.cos(imag2);
        double expectedReal = Math.sinh(real2) / d;
        double expectedImag = Math.sin(imag2) / d;

        Assert.assertEquals(expectedReal, result.getReal(), EPSILON);
        Assert.assertEquals(expectedImag, result.getImaginary(), EPSILON);
    }
}
